  private readonly _boxed = this.box(new Emitter<string>());
  private readonly _kept = this.keep(new Emitter<string>());
  private readonly _widget = this.replace(new FancyWidget());
  private readonly items = new Set<Emitter<string>>();
  private readonly _set = this.items.add(new Emitter<string>());
  private box<T>(value: T): Box<T> {
    return new Box(value);
  }
  private keep<T>(value: T) {
    return value;
  }
  private replace(widget: Widget): Widget {
    return widget instanceof FancyWidget ? new Widget() : widget;
  }
  run() {
    this._boxed.fire('a');
    this._kept.fire('b');
    this._widget.fire();
    this._set.fire('c');
  }
}

